import{_ as u,a0 as r,w as s,s as a,ao as x,I as i,x as n,a1 as l,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"選擇 Linux 的五大好處 | LCTT x X-CMD","titleTemplate":false,"description":"選擇 Linux 的五大好處 | LCTT (202104) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"選擇 Linux 的五大好處 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"選擇 Linux 的五大好處 | LCTT (202104) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202104/20210222 5 benefits of choosing Linux","title":"選擇 Linux 的五大好處","tag":"202104","desc":""},"relativePath":"202104/20210222 5 benefits of choosing Linux.md","filePath":"[post].md"}'),p={name:"202104/20210222 5 benefits of choosing Linux.md"};function d(L,t,m,f,b,T){const e=r("Link");return s(),a("div",null,[t[21]||(t[21]=x('<h1 id="選擇-linux-的五大好處" tabindex="-1">選擇 Linux 的五大好處 <a class="header-anchor" href="#選擇-linux-的五大好處" aria-label="Permalink to “選擇 Linux 的五大好處”">​</a></h1><blockquote><p>Linux 的一大優點是多樣化選擇，選擇激發了用户之間自由分享想法和解決方案。Linux 將如何激發你為這個社區做出貢獻呢？</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202104/10/131305ei6yyuyujui9fkkr.jpg" alt=""></p><p>到了 2021 年，人​​們比以往任何時候都更有理由喜歡 Linux。在本系列中，我將分享 21 個使用 Linux 的理由。本文討論選擇 Linux 帶來的好處。</p><p><em>選擇</em> 是 Linux 中被誤解最深的特性之一。這種誤解從可被選擇的 Linux 發行版數量就開始了。Distrowatch.org 報告了數百種可用的和活躍的 Linux 發行版。當然，在這些發行版當中，許多都是業餘愛好項目或者針對某些晦澀需求的特別版。因為是開源的，所以實際上，任何人都可以“重新設計”或“重新混搭”現有的 Linux 發行版，賦予一個新名稱，提供一個新的默認牆紙，然後稱其為自己的作品。儘管這些修改似乎微不足道，但我認為這顯示了 Linux 的一些特別之處。</p><h3 id="靈感" tabindex="-1">靈感 <a class="header-anchor" href="#靈感" aria-label="Permalink to “靈感”">​</a></h3><p>Linux 似乎一直在啓迪着人們，從瞭解它的那一刻起，到創造出自己的版本。</p><p>有數十家公司花費數百萬美元來從他們自己的產品中獲取靈感。商業技術廣告試着強硬地説服你，只要你購買某種產品，你就會與所關心的人建立更多的聯繫，更具創造力、更加充滿活力。這些廣告用 4k 視頻拍攝，焦點柔和，並在歡快振奮的音樂節奏下播放，試圖説服人們不僅購買而且還要支持和宣傳該公司的產品。</p><p>當然，Linux 基本沒有營銷預算，因為 Linux 是個形形色色的大集合，<em>沒有固定實體</em>。然而，當人們發現它的存在時候，他們似乎就被啓發着去構建屬於自己的版本。</p><p>靈感的數量很難量化，但是它顯然很有價值，要不然那些公司不會花錢來嘗試創造靈感。</p><h3 id="革新" tabindex="-1">革新 <a class="header-anchor" href="#革新" aria-label="Permalink to “革新”">​</a></h3>',11)),i("p",null,[t[1]||(t[1]=n("靈感，無論給它標價有多難，它都因它的生產創造而有價值。許多 Linux 用户受啓發來為各種奇怪問題定製解決方案。我們解決的大多數問題，對於其他大部分人而言，似乎微不足道：也許你使用 ",-1)),l(e,{href:"https://opensource.com/article/19/12/seeeduino-nano-review"},{default:o(()=>[...t[0]||(t[0]=[n("Seeed 微控制器",-1)])]),_:1}),t[2]||(t[2]=n(" 來監控番茄植株土壤的水分含量；或者你使用腳本來搜索 Python 軟件包的索引，因為你總是會忘記每天導入的庫的名稱；或者設置了自動清理下載文件夾，因為將文件圖標拖進回收站這個活兒幹太多了。不管你在使用 Linux 的過程中，為自己解決過什麼問題，都是這個平台包含的特性之一，你被這個正在運行中的開放的技術所啓發，使其更好地服務於你自己。",-1))]),t[22]||(t[22]=i("h3",{id:"開放策略",tabindex:"-1"},[n("開放策略 "),i("a",{class:"header-anchor",href:"#開放策略","aria-label":"Permalink to “開放策略”"},"​")],-1)),t[23]||(t[23]=i("p",null,"誠然，不論是靈感，還是創新，都不能算 Linux 獨有的屬性。其他平台也確實讓我們激發靈感，我們也以或大或小的方式進行創新。運算能力已在很大程度上拉平了操作系統的競爭領域，你在一個操作系統上可以完成的任何事，在另一個操作系統上或許都能找到對應的方法來完成。",-1)),t[24]||(t[24]=i("p",null,"但是，許多用户發現，Linux 操作系統保留了堅定的開放策略，當你嘗試可能無人想到過的嘗試時，Linux 不會阻擋你。這種情況不會也不可能發生在專有的操作系統上，因為無法進入系統層級的某些區域，因為它們本身就是被設計為不開放源碼的。有各種獨斷的封鎖。當你完全按照操作系統的期望進行操作時，你不會碰到那些看不見的牆，但是當你心裏想着要做一些只對你有意義的事情的時候，你的系統環境可能變得無從適應。",-1)),t[25]||(t[25]=i("h3",{id:"小小的選擇-大大的意義",tabindex:"-1"},[n("小小的選擇，大大的意義 "),i("a",{class:"header-anchor",href:"#小小的選擇-大大的意義","aria-label":"Permalink to “小小的選擇，大大的意義”"},"​")],-1)),i("p",null,[t[4]||(t[4]=n("並非所有創新都是大的或重要的，但總的來説，它們帶來的變化並不小。如今，數百萬用户的那些瘋狂想法在 Linux 的各個部分中愈發顯現。它們存在於 KDE 或 GNOME 桌面的工作方式中，存在於 ",-1)),l(e,{href:"https://opensource.com/article/21/1/text-editor-roundup"},{default:o(()=>[...t[3]||(t[3]=[n("31 種不同的文本編輯器",-1)])]),_:1}),t[5]||(t[5]=n(" 中 —— 每一種都有人喜愛，存在於不計其數的瀏覽器插件和多媒體應用程序中，存在於文件系統和擴展屬性中，以及數以百萬行計的 Linux 內核代碼中。而且，如果上述功能中的哪怕僅其中一項，能讓你每天額外節省下一小時時間，陪家人、朋友或用在自己的業餘愛好上，那麼按照定義，套用一句老話就是，“改變生活”。",-1))]),t[26]||(t[26]=i("h3",{id:"在社區中交流",tabindex:"-1"},[n("在社區中交流 "),i("a",{class:"header-anchor",href:"#在社區中交流","aria-label":"Permalink to “在社區中交流”"},"​")],-1)),t[27]||(t[27]=i("p",null,"開源的重要組成部分之一是共享工作。共享代碼是開源軟件中顯而易見的、普遍流行的事務，但我認為，分享，可不僅僅是在 Gitlab 做一次提交那麼簡單。當人們彼此分享着自己的奇思妙想，除了獲得有用的代碼貢獻作為回報外，再無其他動機，我們都認為這是一種饋贈。這與你花錢從某公司購買軟件時的感覺非常不同，甚至與得到某公司對外分享他們自己生產的開源代碼時的感覺也有很大不同。開源的實質是，由全人類創造，服務於全人類。當知識和靈感可以被自由地分享時，人與人之間就建立了連接，這是市場營銷活動無法複製的東西，我認為我們都認同這一點。",-1)),t[28]||(t[28]=i("h3",{id:"選擇",tabindex:"-1"},[n("選擇 "),i("a",{class:"header-anchor",href:"#選擇","aria-label":"Permalink to “選擇”"},"​")],-1)),t[29]||(t[29]=i("p",null,"Linux 並不是唯一擁有很多選擇的平台。無論使用哪種操作系統，你都可以找到針對同一問題的多種解決方案，尤其是在深入研究開源軟件的時候。但是，Linux 明顯的選擇水準指示了推動 Linux 前進的因素：誠邀協作。在 Linux 上，有些創造會很快消失，有些會在你家用電腦中保留數年 —— 即便只是執行一些不起眼的自動化任務，然而有一些則非常成功，以至於被其他系統平台借鑑並變得司空見慣。沒關係，無論你在 Linux 上創作出什麼，都請毫不猶豫地把它加入千奇百怪的選擇之中，你永遠都不知道它可能會激發到誰的靈感。",-1)),t[30]||(t[30]=i("hr",null,null,-1)),i("p",null,[t[7]||(t[7]=n("via: ",-1)),l(e,{href:"https://opensource.com/article/21/2/linux-choice"},{default:o(()=>[...t[6]||(t[6]=[n("https://opensource.com/article/21/2/linux-choice",-1)])]),_:1})]),i("p",null,[t[12]||(t[12]=n("作者：",-1)),l(e,{href:"https://opensource.com/users/seth"},{default:o(()=>[...t[8]||(t[8]=[n("Seth Kenlon",-1)])]),_:1}),t[13]||(t[13]=n(" 選題：",-1)),l(e,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[9]||(t[9]=[n("lujun9972",-1)])]),_:1}),t[14]||(t[14]=n(" 譯者：",-1)),l(e,{href:"https://github.com/max27149"},{default:o(()=>[...t[10]||(t[10]=[n("max27149",-1)])]),_:1}),t[15]||(t[15]=n(" 校對：",-1)),l(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[11]||(t[11]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[18]||(t[18]=n("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[16]||(t[16]=[n("LCTT",-1)])]),_:1}),t[19]||(t[19]=n(" 原創編譯，",-1)),l(e,{href:"https://linux.cn/"},{default:o(()=>[...t[17]||(t[17]=[n("Linux中國",-1)])]),_:1}),t[20]||(t[20]=n(" 榮譽推出",-1))])])}const P=u(p,[["render",d]]);export{C as __pageData,P as default};
